  ];
  var W = [
    [1, 1, 1, 1, 1, 1, 1, 1],
    [1.2, 1.2, 1.3, 1.38, 1.38, 1.26, 1.06, 1.02],
    [1.05, 1.04, 1.07, 1.12, 1.15, 1.05, 0.95, 0.97],
    [1.05, 1.04, 1.07, 1.1, 1.12, 1.04, 0.95, 0.97],
