  var E = [1, 1.2, 1.06, 1.06, 0.95, 0.84, 0.79, 0.9];          // eye spacing
  var S = [1, 1.08, 1.02, 1.02, 0.98, 0.95, 0.95, 0.97];        // eye size
  var D = [0, 0.75, 0.8, 0.75, 0, 0, 0, 0];                     // dark arm tips
  var M = [1.3, 1.55, 1.33, 1.3, 0.95, 0.8, 0.72, 0.9];         // mouth width
  // arm stretch per unit of length along the arm (left arm space; right arm is mirrored)
  var AX = [0, -0.04, -0.04, -0.04, 0.131, 0.131, 0.138, 0.124];
  var AY = [0, 0.12, 0.12, 0.12, -0.335, -0.335, -0.354, -0.317];
  var B = [0, 0, 0, 0, 0.08, 0.09, 0.08, 0.07];                 // lower belly bulge of the torso outline
  Y.push(Y[0]); W.push(W[0]); E.push(E[0]); S.push(S[0]); D.push(D[0]);
  M.push(M[0]); AX.push(AX[0]); AY.push(AY[0]); B.push(B[0]);

  var yl = [], wl = [];
  function seg(y) { var i = 0; while (i < L.length - 2 && y > L[i + 1]) i++; return i; }
  function wy(y) { var i = seg(y), f = (y - L[i]) / (L[i + 1] - L[i]); return yl[i] + (yl[i + 1] - yl[i]) * f; }
  function ww(y) {
    var i = seg(y), f = Math.max(0, Math.min(1, (y - L[i]) / (L[i + 1] - L[i])));
    return wl[i] + (wl[i + 1] - wl[i]) * f;
