  function wx(x, y) { return 152 + (x - 152) * ww(y); }
  function bump(y) { var d = (y - 236) / 32; return (d > -1 && d < 1) ? 1 - d * d : 0; }
  function r1(v) { return Math.round(v * 10) / 10; }
  function $(id) { return document.getElementById(id); }

  // 1 = left arm, 2 = right arm, 3 = mouth, 4 = torso outline, 0 = everything else
  function kind(el) {
