  // lengthen / shorten an arm from its shoulder pivot (rest space)
  function armPt(x, y, side, ax, ay) {
    var mx = side === 1 ? x : 304 - x;
    var along = (mx - 76) * -0.3636 + (y - 127) * 0.9316;
    if (along < 0) along = 0;
    mx += ax * along;
    y += ay * along;
    return [side === 1 ? mx : 304 - mx, y];
  }

  var P = [].map.call(svg.querySelectorAll('path'), function (p) {
    return { el: p, k: kind(p), tk: p.getAttribute('d').match(/[A-Za-z]|-?\d*\.?\d+/g) };
