          }
          s += r1(ox) + ',' + r1(oy) + ' ';
          j += 2;
        }
      }
      p.el.setAttribute('d', s);
    }

    // warp soft shading ellipses
    for (i = 0; i < EL.length; i++) {
      var e = EL[i], cx = e.cx, cy = e.cy;
      if (e.k === 1 || e.k === 2) { q = armPt(cx, cy, e.k, ax, ay); cx = q[0]; cy = q[1]; }
